/// A confirmation that accepts every value: the states' default `confirm_value_change`, for
/// the defaults that remember a state (`ModalNavigationDrawer`'s, `ModalBottomSheet`'s).
#[doc(hidden)]
pub fn always_confirm<T: 'static>() -> compose_runtime::Callback<dyn Fn(T) -> bool> {
    compose_runtime::callback(|_: T| true)
}

#[doc(hidden)]
pub fn window_default_dialog_properties() -> compose_ui::DialogProperties {
    compose_ui::DialogProperties::default()
}

/// `Scrim`'s default `on_click`: nothing, one callback per thread (the same every pass, so the
/// scrim can skip).
#[doc(hidden)]
pub fn scrim_default_on_click() -> Option<compose_runtime::Callback> {
    thread_local! {
        static CLICK: compose_runtime::Callback = compose_runtime::callback(|| {});
    }
    Some(CLICK.with(Clone::clone))
}

/// `ModalBottomSheet`'s default `drag_handle`: `BottomSheetDefaults::drag_handle`, one callback
/// per thread (the same every pass, so the sheet can skip).
#[doc(hidden)]
pub fn default_drag_handle() -> Option<compose_runtime::Callback> {
    thread_local! {
        static HANDLE: compose_runtime::Callback =
            compose_runtime::callback(BottomSheetDefaults::drag_handle);
    }
    Some(HANDLE.with(Clone::clone))
}
